UPDATE events e SET image_url=m.image, details=e.details || m.details FROM media m
WHERE e.is_sample AND e.slug=m.slug;
-- Demo hours are part of the illustrative catalogue, not verified real-world opening hours.
UPDATE events SET details=details || jsonb_build_object(
  'dailyStart', to_char(starts_at AT TIME ZONE 'Asia/Riyadh','HH24:MI'),
  'dailyEnd', to_char(ends_at AT TIME ZONE 'Asia/Riyadh','HH24:MI'))
WHERE is_sample AND ends_at-starts_at > interval '24 hours' AND slug <> 'taibah-student-hackathon';
UPDATE events SET title='سباق المدينة ٥ كم' WHERE is_sample AND slug='madinah-5k-run';
-- Synthetic channels stay explicitly identified and never overwrite real interaction attribution.
UPDATE interactions SET meta=meta || jsonb_build_object('source',
  (ARRAY['home','search','list','map','recommendation','shared'])[1+(id % 6)::int], 'synthetic',true)
WHERE is_sample AND type='view' AND NOT(meta ? 'source');
